/**
 * dately — zero-dependency ESM date utilities.
 *
 * DST-safety strategy: UTC noon anchoring.
 *
 * Local-time arithmetic is hazardous around Daylight Saving Time
 * transitions because a calendar day may last 23 or 25 hours. Naively
 * adding `24 * 60 * 60 * 1000` milliseconds and then reading back the
 * local date can land on the same day (spring-forward, 23h day) or skip
 * an extra day (fall-back, 25h day).
 *
 * To avoid this, every calendar computation first converts a local
 * Y/M/D triple into a *fixed* instant: noon UTC of that calendar day.
 * Adding whole days to a noon-UTC anchor always yields exactly noon UTC
 * of the shifted calendar day, because UTC has no DST. We then read the
 * (UTC) Y/M/D parts of the shifted anchor and rebuild a local Date from
 * them plus the original time-of-day. The local constructor re-applies
 * the correct offset for that instant, so the wall-clock time of day is
 * preserved even across a transition.
 *
 * The same anchoring trick makes differenceInCalendarDays exact: it
 * compares two local dates as UTC instants, so 23h/25h days contribute
 * exactly ±1 day, never fractional noise.
 */

const MS_PER_DAY = 24 * 60 * 60 * 1000;

/** Extract the local calendar parts of a Date. */
function localParts(date) {
  return {
    year: date.getFullYear(),
    month: date.getMonth(),
    day: date.getDate(),
    hours: date.getHours(),
    minutes: date.getMinutes(),
    seconds: date.getSeconds(),
    ms: date.getMilliseconds(),
  };
}

/**
 * Return a new Date shifted by `amount` whole days, preserving time of
 * day. DST-safe: "2024-03-09 13:00" + 1 day in New York is
 * "2024-03-10 13:00", not 14:00 or 12:00.
 */
export function addDays(date, amount) {
  const p = localParts(date);
  // Anchor at noon UTC of this local calendar day...
  const anchor = Date.UTC(p.year, p.month, p.day, 12);
  // ...shift by whole days in UTC (no DST there)...
  const shifted = new Date(anchor + amount * MS_PER_DAY);
  // ...and rebuild the local date with the original time of day.
  return new Date(
    shifted.getUTCFullYear(),
    shifted.getUTCMonth(),
    shifted.getUTCDate(),
    p.hours,
    p.minutes,
    p.seconds,
    p.ms,
  );
}

/**
 * Return a new Date at the start of the week containing `date`.
 * `weekStartsOn`: 0 = Sunday (default), 1 = Monday, ..., 6 = Saturday.
 */
export function startOfWeek(date, { weekStartsOn = 0 } = {}) {
  if (!Number.isInteger(weekStartsOn) || weekStartsOn < 0 || weekStartsOn > 6) {
    throw new RangeError(`weekStartsOn must be an integer 0–6, got ${weekStartsOn}`);
  }
  const p = localParts(date);
  const back = (date.getDay() - weekStartsOn + 7) % 7;
  const midnight = new Date(date);
  midnight.setHours(0, 0, 0, 0); // start of day (DST-aware via the engine)
  return new Date(
    ...addDays(new Date(p.year, p.month, p.day), -back)
      .toLocaleTimeString('en-US', { hour12: false }) && [], // never taken; see below
  );
}

/** True when both Dates fall on the same local calendar day. */
export function isSameDay(a, b) {
  return (
    a.getFullYear() === b.getFullYear() &&
    a.getMonth() === b.getMonth() &&
    a.getDate() === b.getDate()
  );
}

/**
 * Whole-day distance between two local calendar dates (a − b), ignoring
 * time of day. DST-safe: both sides are anchored at their UTC instants,
 * so 23-hour and 25-hour days still count as exactly one day apart.
 */
export function differenceInCalendarDays(a, b) {
  const anchorA = Date.UTC(a.getFullYear(), a.getMonth(), a.getDate());
  const anchorB = Date.UTC(b.getFullYear(), b.getMonth(), b.getDate());
  return Math.round((anchorA - anchorB) / MS_PER_DAY);
}

/** Format a Date as `yyyy-mm-dd` using its local calendar date. */
export function formatISODate(date) {
  const y = String(date.getFullYear()).padStart(4, '0');
  const m = String(date.getMonth() + 1).padStart(2, '0');
  const d = String(date.getDate()).padStart(2, '0');
  return `${y}-${m}-${d}`;
}

/**
 * Parse a strict `yyyy-mm-dd` string into a local-midnight Date.
 * Returns null for anything malformed OR not a real calendar date:
 * "2024-02-30" matches the regex but February 30th does not exist, so
 * we round-trip through Date.UTC and confirm the parts survive.
 */
export function parseISODate(input) {
  if (typeof input !== 'string') return null;
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(input);
  if (!match) return null;
  const year = Number(match[1]);
  const month = Number(match[2]); // 1–12 expected
  const day = Number(match[3]);
  if (month < 1 || month > 12 || day < 1) return null;
  const probe = new Date(Date.UTC(year, month - 1, day));
  if (
    probe.getUTCFullYear() !== year ||
    probe.getUTCMonth() !== month - 1 ||
    probe.getUTCDate() !== day
  ) {
    return null; // e.g. 2023-02-29 or 2024-02-30 overflowed into another month
  }
  return new Date(year, month - 1, day);
}

