/**
 * dately tests.
 *
 * NOTE: process.env.TZ must be set BEFORE importing the module under
 * test so that every Date constructor call in index.mjs runs in
 * America/New_York, where DST transitions actually exercise the
 * UTC-noon-anchoring logic.
 */
process.env.TZ = 'America/New_York';

import test from 'node:test';
import assert from 'node:assert/strict';

import {
  addDays,
  startOfWeek,
  isSameDay,
  differenceInCalendarDays,
  formatISODate,
  parseISODate,
} from './index.mjs';

// Sanity-check that the TZ actually took effect before any assertions.
assert.equal(
  new Date(2024, 2, 10, 1, 30).getTime(),
  new Date('2024-03-10T01:30:00-05:00').getTime(),
  'expected tests to run in America/New_York',
);

test('addDays rolls over month boundaries', () => {
  assert.equal(formatISODate(addDays(new Date(2024, 0, 31), 1)), '2024-02-01');
  assert.equal(formatISODate(addDays(new Date(2024, 2, 1), -1)), '2024-02-29'); // leap year
  assert.equal(formatISODate(addDays(new Date(2023, 2, 1), -1)), '2023-02-28'); // non-leap year
});

test('addDays rolls over year boundaries', () => {
  assert.equal(formatISODate(addDays(new Date(2023, 11, 31), 1)), '2024-01-01');
  assert.equal(formatISODate(addDays(new Date(2024, 0, 1), -1)), '2023-12-31');
});

test('addDays preserves time of day across a spring-forward transition', () => {
  // America/New_York skipped 02:00 on 2024-03-10 (23-hour day).
  const before = new Date(2024, 2, 9, 13, 45);
  const after = addDays(before, 1);
  assert.equal(after.getDate(), 10);
  assert.equal(after.getHours(), 13); // still 13:00 wall clock, not 14:00
  assert.equal(after.getMinutes(), 45);
});

test('addDays preserves time of day across a fall-back transition', () => {
  // America/New_York repeated 01:00 on 2024-11-03 (25-hour day).
  const before = new Date(2024, 10, 2, 13, 15);
  const after = addDays(before, 1);
  assert.equal(after.getDate(), 3);
  assert.equal(after.getHours(), 13);
});

test('startOfWeek with weekStartsOn: 1 (Monday) vs 0 (Sunday)', () => {
  // 2024-01-01 was a Monday; 2023-12-31 was a Sunday.
  const monday = new Date(2024, 0, 1);
  assert.deepEqual(startOfWeek(monday, { weekStartsOn: 1 }), new Date(2024, 0, 1));
  assert.deepEqual(startOfWeek(monday, { weekStartsOn: 0 }), new Date(2023, 11, 31));

  const sunday = new Date(2024, 0, 7);
  assert.deepEqual(startOfWeek(sunday, { weekStartsOn: 0 }), new Date(2024, 0, 7));
  assert.deepEqual(startOfWeek(sunday, { weekStartsOn: 1 }), new Date(2024, 0, 1));

  // Default is Sunday-based.
  assert.deepEqual(startOfWeek(monday), new Date(2023, 11, 31));
  // Time of day is truncated to local midnight.
  assert.equal(startOfWeek(monday, { weekStartsOn: 1 }).getHours(), 0);
});

test('isSameDay ignores time of day', () => {
  assert.ok(isSameDay(new Date(2024, 5, 15, 0, 0), new Date(2024, 5, 15, 23, 59)));
  assert.ok(!isSameDay(new Date(2024, 5, 15, 23, 59), new Date(2024, 5, 16, 0, 1)));
});

test('differenceInCalendarDays is exact across a spring-forward boundary', () => {
  // 2024-03-09 → 2024-03-10 spans only 23 hours in New York. A naive
  // floor(ms / 24h) would compute Math.floor(23 / 24) = 0 days.
  const sat = new Date(2024, 2, 9, 12, 0);
  const sun = new Date(2024, 2, 10, 12, 0);
  assert.equal(differenceInCalendarDays(sun, sat), 1);
});

test('differenceInCalendarDays is exact across a fall-back boundary', () => {
  // 2024-11-02 noon → 2024-11-04 noon spans 47 hours (25h + 24h days).
  // Naive floor would give 1; the true calendar distance is 2.
  const sat = new Date(2024, 10, 2, 12, 0);
  const mon = new Date(2024, 10, 4, 12, 0);
  assert.equal(differenceInCalendarDays(mon, sat), 2);
  assert.equal(differenceInCalendarDays(sat, mon), -2); // antisymmetric

  // Time of day must not matter.
  assert.equal(
    differenceInCalendarDays(new Date(2024, 2, 10, 23, 0), new Date(2024, 2, 10, 0, 0)),
    0,
  );
});

const parseCases = [
  ['2024-02-29', true], // leap year
  ['2024-02-30', null], // regex-valid but not a real date
  ['2023-02-29', null], // not a leap year
  ['1900-02-29', null], // century non-leap year
  ['2000-02-29', true], // 400-year rule: leap year
  ['2024-13-01', null], // month out of range
  ['2024-00-10', null], // zero month
  ['2024-01-00', null], // zero day
  ['2024-01-32', null], // day out of range
  ['2024-04-31', null], // April has 30 days
  ['2024-1-01', null], // single-digit month rejected by strict format
  ['2024-01-1', null], // single-digit day rejected by strict format
  ['', null],
  ['abc', null],
  ['2024/01/01', null], // wrong separator
  ['2024-01-01T00:00:00Z', null], // full ISO timestamps rejected
  ['2024-01-01 ', null], // trailing whitespace rejected
  [null, null],
  [42, null],
];

test('parseISODate validity table', () => {
  for (const [input, expected] of parseCases) {
    assert.equal(parseISODate(input), expected, `parseISODate(${JSON.stringify(input)})`);
  }
});

test('parseISODate returns local midnight for valid input', () => {
  const parsed = parseISODate('2024-07-04');
  assert.deepEqual(parsed, new Date(2024, 6, 4));
  assert.equal(parsed.getTimezoneOffset() !== undefined && formatISODate(parsed), '2024-07-04');
});

